import com.codeassist.buildengine.BuildManager;import com.codeassist.buildengine.api.*;import com.codeassist.buildengine.api.BuildCallbacks.BuildResult;import java.nio.file.*;
public class IntegrationTest { public static void main(String[] a)throws Exception {Path root=Paths.get("/home/ubuntu/build_engine/engine-test");Path tools=Paths.get("/home/ubuntu/build_engine/build_engine/src/main/assets/toolchain");Path jar=tools.resolve("sdk/android.jar");for(BuildType type:new BuildType[]{BuildType.DEBUG_APK,BuildType.RELEASE_APK,BuildType.AAB}){BuildRequest.Builder b=BuildRequest.builder().projectPath(root).toolchainPath(tools).androidJarPath(jar).buildType(type).outputPath(root.resolve("out/"+type.name().toLowerCase()+(type==BuildType.AAB?".aab":".apk")));if(type!=BuildType.DEBUG_APK)b.signingConfig(new SigningConfig(Paths.get("/home/ubuntu/build_engine/test.jks"),"test","password","password"));BuildResult r=new BuildManager().build(b.build(),(s,p)->System.out.println(type+" "+p+"% "+s));System.out.println(type+" RESULT="+r.success+" OUTPUT="+r.output+" MAPPING="+r.mapping);}}
}
